<script setup>
import { computed, onMounted, ref, watch } from 'vue';
import ShoppingLinks from './ShoppingLinks.vue';
import ProductImage from './ProductImage.vue';
import TaobaoSettings from './TaobaoSettings.vue';
const catalog=ref({products:[],categories:[],brands:[],counts:[],subcategories:[]}), category=ref(''),subcategory=ref(''),brand=ref(''),q=ref(''),detail=ref(null),loading=ref(false),error=ref('');
const curatedOnly=ref(true);
const quoteUrl=ref(''),quoteMessage=ref(''),quoteBusy=ref(false);
let serial=0;
const types=computed(()=>(catalog.value.subcategories||[]).filter(x=>!category.value||x.category===category.value));
const total=computed(()=>catalog.value.counts.reduce((sum,c)=>sum+c.count,0));
async function load(){const seq=++serial;loading.value=true;error.value='';try{const response=await fetch('/api/catalog?'+new URLSearchParams({curated:curatedOnly.value?'1':'',category:category.value,brand:brand.value,subcategory:subcategory.value,q:q.value}));if(!response.ok)throw new Error('产品库加载失败，请检查后端服务');const data=await response.json();if(seq===serial)catalog.value=data;}catch(e){if(seq===serial)error.value=e.message;}finally{if(seq===serial)loading.value=false;}}
async function inspect(p){error.value='';quoteUrl.value='';quoteMessage.value='';try{const r=await fetch('/api/catalog/'+p.id);if(!r.ok)throw new Error('参数加载失败');detail.value=await r.json();}catch(e){error.value=e.message;}}
async function updateQuote(){if(!detail.value||!quoteUrl.value.trim())return;quoteBusy.value=true;quoteMessage.value='正在核对公开页面与当前型号…';try{const response=await fetch('/api/quotes/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:detail.value.id,url:quoteUrl.value.trim()})});const result=await response.json();if(!response.ok)throw new Error(result.error);quoteMessage.value=result.message;const fresh=await fetch('/api/catalog/'+detail.value.id);detail.value=await fresh.json();await load()}catch(e){quoteMessage.value=e.message}finally{quoteBusy.value=false}}
const timestamp=value=>new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'});
async function updateTaobao(){if(!detail.value)return;quoteBusy.value=true;quoteMessage.value='正在调用淘宝 API…';try{const r=await fetch('/api/taobao/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product_id:detail.value.id})});const data=await r.json();if(!r.ok)throw new Error(data.error);quoteMessage.value=data.message;const fresh=await fetch('/api/catalog/'+detail.value.id);detail.value=await fresh.json();await load()}catch(e){quoteMessage.value=e.message}finally{quoteBusy.value=false}}
watch(category,()=>{subcategory.value='';load()});watch([brand,subcategory,curatedOnly],load);onMounted(load);
</script>
<template>
<section class="catalog-page">
 <details class="platform-config"><summary>平台 API 设置（可选）</summary><TaobaoSettings /></details>
 <div class="eyebrow">OFFICIAL PRODUCT CATALOG</div><h1>品牌官网产品库</h1><p class="catalog-desc">查看官方参数，按类别、细分类别和品牌筛选。每款产品都提供购物平台搜索入口，方便查价和选购。</p>
 <div class="catalog-stats"><div><strong>{{total}}</strong><span>个产品型号 / 系列</span></div><div><strong>{{catalog.brands.length}}</strong><span>个品牌</span></div><div><strong>{{catalog.subcategories?.length || 0}}</strong><span>种细分类别</span></div><div><strong>4</strong><span>个购物平台入口</span></div></div>
 <div class="category-pills"><button :class="{chosen:!category}" @click="category=''">全部产品</button><button v-for="c in catalog.categories" :key="c" :class="{chosen:category===c}" @click="category=c">{{c}} <small>{{catalog.counts.find(x=>x.category===c)?.count||0}}</small></button></div>
 <div class="dossier-banner"><div><span class="eyebrow">SOURCE-BACKED DOSSIERS</span><h2>{{catalog.curated_count||25}} 款代表产品 · 五大品类</h2><p>官方图片、参数原文、报价配置与采集时间，一起留档。</p></div><label><input v-model="curatedOnly" type="checkbox"/>仅看精选资料档案</label></div><div class="catalog-toolbar"><el-select v-model="brand" clearable placeholder="全部品牌" style="width:180px"><el-option v-for="b in catalog.brands" :key="b" :label="b" :value="b"/></el-select><el-select v-model="subcategory" clearable placeholder="全部细分类别" style="width:180px"><el-option v-for="t in types" :key="t.category+t.subcategory" :label="t.subcategory+'（'+t.count+'）'" :value="t.subcategory"/></el-select><input v-model="q" placeholder="搜索型号或品牌" @keyup.enter="load"><button class="text-btn" @click="load">搜索</button></div>
 <p v-if="error" class="catalog-error" role="alert">{{error}} <button @click="load">重试</button></p>
 <div v-loading="loading" class="catalog-list"><article v-for="p in catalog.products" :key="p.id" class="catalog-product"><div class="catalog-product-top"><span class="assist-tag">{{p.category}}</span><span>{{p.region}}</span></div><ProductImage :product="p"/><small>{{p.brand}} · {{p.subcategory}}</small><h3>{{p.name}}</h3><p>{{p.spec_count}} 组官网原始参数 <span v-if="p.curated">· 精选档案</span></p><div class="catalog-price">{{p.price==null?'到平台查看报价':'¥'+Number(p.price).toLocaleString()+(p.offer?.price_type==='官网起售价'?' 起':'')}}</div><p v-if="p.offer" class="offer-summary">{{p.offer.merchant}} · {{p.offer.price_type}}<br>{{p.offer.variant}}<br>报价采集于 {{timestamp(p.offer.observed_at)}}</p><div class="catalog-date">参数采集于 {{timestamp(p.collected_at)}}</div><ShoppingLinks :product="p"/><div class="catalog-actions"><button class="text-btn" @click="inspect(p)">查看参数</button><a :href="p.source_url" target="_blank" rel="noopener noreferrer">品牌官网 ↗</a></div></article></div>
 <el-empty v-if="!loading&&!catalog.products.length&&!error" description="未找到匹配产品，请调整筛选条件"/>
 <p class="catalog-footnote">共 {{catalog.products.length}} 条匹配资料。系列页可能包含多种配置，请保留参数中的型号、尺寸和条件说明。官方参数库不包含虚构评价、评分或价格趋势。</p>
 <el-dialog :model-value="!!detail" @close="detail=null" width="min(900px, 94vw)" :title="detail?.name" destroy-on-close><template v-if="detail"><p>{{detail.brand}} · {{detail.subcategory}} · {{detail.region}}</p><p class="catalog-date">来源：<a :href="detail.source_url" target="_blank" rel="noopener noreferrer">{{detail.source_title}}</a><br>采集时间：{{timestamp(detail.collected_at)}}（北京时间）</p><div v-if="detail.curated" class="dossier-evidence"><ProductImage :product="detail"/><div><h3>资料与配置凭据</h3><p>{{detail.curated.configuration}}</p><p>{{detail.curated.note}}</p><a :href="detail.curated.image_source_url" target="_blank" rel="noopener noreferrer">官网图片原始来源 ↗</a><p>图片指纹 SHA-256：{{detail.curated.image_sha256.slice(0,20)}}…</p></div></div><p>{{detail.price_note}}</p><ShoppingLinks :product="detail"/><section v-if="detail.offers?.length" class="offer-table"><h3>已采集报价</h3><p>具体配置标价与平台参考价分开标注；全新、二手及库存状态分别核对。超过 7 天的记录仅作历史资料。</p><table><thead><tr><th>配置 / 店铺</th><th>报价</th><th>时间 / 来源</th></tr></thead><tbody><tr v-for="o in detail.offers" :key="o.id"><td>{{o.variant}}<br>{{o.merchant}}</td><td>¥{{o.amount}}<br>{{o.price_type}}</td><td>{{timestamp(o.observed_at)}}<br><a :href="o.source_url" target="_blank" rel="noopener noreferrer">查看来源 ↗</a></td></tr></tbody></table></section><section class="quote-update"><h3>补充或更新平台报价</h3><button class="secondary-btn" :disabled="quoteBusy" @click="updateTaobao">调用淘宝 API 更新报价</button><p>粘贴此型号的京东、淘宝、拼多多、闲鱼商品页或公开比价页。系统核对型号与价格证据后入库；登录页和无法识别的价格不会导入。</p><div><input v-model="quoteUrl" aria-label="商品报价来源链接" placeholder="https://… 商品或报价页面"/><button class="secondary-btn" :disabled="quoteBusy||!quoteUrl.trim()" @click="updateQuote">{{quoteBusy?'核对中…':'读取公开报价'}}</button></div><p v-if="quoteMessage" role="status">{{quoteMessage}}</p></section><dl class="catalog-specs"><template v-for="(s,i) in detail.specifications" :key="i"><dt>{{s.label}}<small>{{s.section}}</small></dt><dd>{{s.value}}</dd></template></dl></template></el-dialog>
</section>
</template>
<style scoped>
.catalog-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:22px 0}.catalog-stats>div{background:#fff;border:1px solid #e7e9f3;border-radius:12px;padding:17px}.catalog-stats strong{display:block;font-size:25px;color:#6258e8}.catalog-stats span{display:block;font-size:11px;color:#9398ac;margin-top:6px}.catalog-page h1{font-size:30px;margin:12px 0}.catalog-desc{color:#888da2;font-size:13px;line-height:1.8}.category-pills{display:flex;gap:10px;flex-wrap:wrap;margin:28px 0 20px}.category-pills button{background:white;color:#666b83;border:1px solid #e5e7f0;border-radius:10px;padding:11px 20px}.category-pills .chosen{background:#665deb;color:white;border-color:#665deb}.category-pills small{opacity:.7;margin-left:5px}.catalog-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:22px;flex-wrap:wrap}.catalog-toolbar input{border:1px solid #dddfee;border-radius:7px;padding:9px 12px;background:white;flex:1;min-width:150px}.catalog-toolbar a,.catalog-actions a{font-size:12px;color:#675ee2}.catalog-list{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;min-height:100px}.catalog-product{background:white;border:1px solid #e7e9f3;border-radius:15px;padding:22px}.catalog-product-top{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.catalog-product-top>span:last-child{font-size:10px;color:#9297a8}.catalog-product>small{color:#969bad}.catalog-product h3{font-size:18px;margin:8px 0}.catalog-product p{color:#9398ac;font-size:12px}.catalog-price{font-size:13px;color:#62677d;margin-top:24px}.catalog-date{font-size:10px;color:#989daf;margin-top:8px;line-height:1.8}.catalog-actions{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #eef0f6;margin-top:18px;padding-top:16px}.catalog-footnote{font-size:12px;color:#9297a8;line-height:1.9;margin-top:24px}.catalog-specs{display:grid;grid-template-columns:160px 1fr;border-top:1px solid #e5e7ef}.catalog-specs dt,.catalog-specs dd{padding:15px 10px;border-bottom:1px solid #e5e7ef;margin:0;white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere}.catalog-specs dt{font-weight:600}.catalog-specs dt small{display:block;font-weight:400;color:#a4a7b5;font-size:10px}.catalog-specs dd{color:#696e83}.catalog-error{color:#c14d57}@media(max-width:1000px){.catalog-list{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.catalog-stats{grid-template-columns:repeat(2,1fr)}.catalog-list{grid-template-columns:1fr}.catalog-specs{grid-template-columns:100px 1fr}}
</style>

<style scoped>
.quote-update{border:1px solid #e8e5f3;border-radius:12px;padding:18px;margin:22px 0}.quote-update p{font-size:12px;color:#8c8fa2;line-height:1.8}.quote-update>div{display:flex;gap:12px;flex-wrap:wrap}.quote-update input{flex:1;min-width:180px;border:1px solid #dddfee;border-radius:8px;padding:10px;font-size:12px}
</style>
